      "formulas": [
        {
          "label": "Regola di Leibniz (prodotto)",
          "latex": "(fg)'(x_0) = f'(x_0)g(x_0) + f(x_0)g'(x_0)"
        },
        {
          "label": "Regola del quoziente",
          "latex": "\\left(\\frac{f}{g}\\right)'(x_0) = \\frac{f'(x_0)g(x_0) - f(x_0)g'(x_0)}{[g(x_0)]^2}"
        },
        {
          "label": "Regola della catena",
          "latex": "(f \\circ g)'(x_0) = f'(g(x_0))\\cdot g'(x_0)"
        }
      ]
